\title{The Algebraic Geometry of ReLU Decision Boundaries:\\
A Depth-Free Tropical Correspondence and an Explicit Boundary Variety}
\author{Aristotle}
\date{2026-07-10}

\begin{document}
\maketitle

\begin{abstract}
Feed-forward neural networks with rectified linear (ReLU) activations compute
continuous piecewise-linear functions, and their decision boundaries are
piecewise-linear hypersurfaces. We establish two structural results that place
these boundaries at the confluence of neural network theory, tropical (max-plus)
geometry, and classical algebraic geometry. First, we prove a \emph{depth-free
characterization}: a real-valued function on $\R^d$ is computable by a
feed-forward ReLU network of arbitrary depth and width if and only if it is a
\emph{tropical rational function}, i.e.\ a difference of two finite maxima of
affine forms. This sharpens the classical one-hidden-layer correspondence to a
two-sided equivalence with no bound on depth. Second, we prove that the decision
boundary of any tropical rational classifier $f = p - q$ is contained in the real
zero locus of a \emph{single, explicit multivariate polynomial}: the product over
all pairs of affine pieces of $p$ and $q$ of their affine differences. Thus every
rectifier decision boundary lies inside a bona fide algebraic hypersurface whose
defining equation we write down in closed form. We show the containment is
generally strict, characterize the source of the strict part, and derive
corollaries, worked examples, algorithms, and conjectures.
\end{abstract}

\section{Introduction}
A feed-forward network with rectified linear units alternates affine maps with the
coordinatewise rectifier $\ReLU(t) = \max(t, 0)$. The resulting function is
continuous and piecewise-linear, and for a scalar output the \emph{decision
boundary} --- the set where the output vanishes --- is a piecewise-linear
hypersurface partitioning input space into decision regions.

Two questions organize this paper. First, which functions can such networks
compute, independently of depth? It is classical that a single hidden layer
computes a difference of two convex piecewise-linear functions, i.e.\ a tropical
rational function; we ask whether depth enlarges the \emph{class} of computable
functions or only the efficiency of their representation. Second, what is the
algebraic nature of the decision boundary? A piecewise-linear hypersurface is not,
a priori, the zero set of a polynomial; we ask whether an explicit algebraic
variety nevertheless contains it. Section~\ref{sec:depth} answers the first and
Section~\ref{sec:variety} the second. Throughout, inputs live in $\R^d$ and
classifiers are scalar-valued.

\section{Definitions}
We work over the reals and fix an input dimension $d \in \mathbb{N}$.

\begin{definition}[Affine functional]
An \emph{affine functional} is specified by a pair $(a,b)$ with $a \in \R^d$ and
$b \in \R$, and evaluates as
\[
  \aff_{(a,b)}(x) = \ip{a}{x} + b = \sum_{j=1}^{d} a_j x_j + b.
\]
\end{definition}

\begin{definition}[Tropical polynomial]
A function $p : \R^d \to \R$ is a \emph{tropical polynomial} if there is a finite
nonempty set $S$ of affine functionals with
$p(x) = \max_{(a,b) \in S}\big(\ip{a}{x} + b\big)$ for all $x$. Every tropical
polynomial is convex and piecewise-linear. In the max-plus semiring
$(\R, \oplus, \odot)$ with $a \oplus b = \max(a,b)$ and $a \odot b = a + b$, such
a $p$ is literally a polynomial expression.
\end{definition}

\begin{definition}[Tropical rational function]
A function $f : \R^d \to \R$ is a \emph{tropical rational function} if there exist
tropical polynomials $p, q$ with $f(x) = p(x) - q(x)$ for all $x$. Such functions
are continuous and piecewise-linear but need not be convex.
\end{definition}

\begin{definition}[Rectifier]
The \emph{rectified linear unit} is $\ReLU(t) = \max(t, 0)$.
\end{definition}

\begin{definition}[Network-computable functions]
The class of \emph{network-computable} functions is the smallest class
$\mathcal{N}$ of functions $\R^d \to \R$ such that: every affine functional
$\aff_{(a,b)}$ is in $\mathcal{N}$; if $f, g \in \mathcal{N}$ then
$x \mapsto f(x)+g(x) \in \mathcal{N}$; if $f \in \mathcal{N}$ and $c \in \R$ then
$x \mapsto c\,f(x) \in \mathcal{N}$; and if $f \in \mathcal{N}$ then
$x \mapsto \ReLU(f(x)) \in \mathcal{N}$. These four generators are exactly the
operations a feed-forward ReLU network performs, iterated to any finite depth and
width.
\end{definition}

\begin{definition}[Decision boundary]
For $f : \R^d \to \R$, the \emph{decision boundary} is the zero locus
$\partial(f) = \{\, x \in \R^d : f(x) = 0 \,\}$.
\end{definition}

\section{The depth-free characterization}\label{sec:depth}

\begin{lemma}[Closure of tropical polynomials]\label{lem:closure}
Let $p, q$ be tropical polynomials. Then \textup{(1)} $\max(p,q)$ is a tropical
polynomial; \textup{(2)} $p+q$ is a tropical polynomial; \textup{(3)} for
$c \ge 0$, $c\,p$ is a tropical polynomial; \textup{(4)} $\ReLU(p)$ is a tropical
polynomial; \textup{(5)} every constant and every affine functional is a tropical
polynomial.
\end{lemma}

\begin{proof}[Proof sketch]
For (1), if $p=\max_S$ and $q=\max_T$ then $\max(p,q)=\max_{S\cup T}$. For (2), the
max-plus distributive law
$\big(\max_{s\in S}u(s)\big)+\big(\max_{t\in T}v(t)\big)
= \max_{(s,t)\in S\times T}(u(s)+v(t))$
gives $p+q = \max_{(a,b)\in S,\,(c,e)\in T}(\ip{a+c}{x}+(b+e))$. For (3), scaling
each piece by $c\ge 0$ preserves the max since $c\max_i z_i = \max_i c z_i$. For
(4), $\ReLU(p)=\max(p,0)$ and $0$ is a constant tropical polynomial, so (4)
follows from (1). Item (5) is immediate.
\end{proof}

\begin{proposition}[Closure under network operations]\label{prop:closure}
The class of tropical rational functions contains all affine functionals and is
closed under addition, real scalar multiplication, and $\ReLU$.
\end{proposition}

\begin{proof}[Proof sketch]
Write tropical rationals as $p-q$. Affine: $\aff_{(a,b)} = \aff_{(a,b)} - 0$.
Addition: $(p_1-q_1)+(p_2-q_2) = (p_1+p_2)-(q_1+q_2)$, using
Lemma~\ref{lem:closure}(2). Negation: $-(p-q) = q-p$; for $c\ge0$,
$c(p-q)=(cp)-(cq)$ by Lemma~\ref{lem:closure}(3), and for $c<0$ combine with
negation to get $c(p-q) = (|c|q)-(|c|p)$. Rectification: the identity
$\ReLU(p-q) = \max(p,q) - q$ writes $\ReLU(p-q)$ as a difference of the tropical
polynomials $\max(p,q)$ and $q$.
\end{proof}

\begin{corollary}[Forward direction]\label{cor:forward}
Every network-computable function is a tropical rational function.
\end{corollary}

\begin{proof}
Induct on the construction; the base and inductive cases are the closure
properties of Proposition~\ref{prop:closure}.
\end{proof}

\begin{lemma}[Maximum via rectifier]\label{lem:maxrelu}
For all $a,b \in \R$, $\max(a,b) = a + \ReLU(b-a)$.
\end{lemma}

\begin{proof}
If $b \ge a$, $\ReLU(b-a)=b-a$ and the right side is $b$. If $b<a$,
$\ReLU(b-a)=0$ and the right side is $a$.
\end{proof}

\begin{proposition}[Maxima are network-computable]\label{prop:max}
If $f,g$ are network-computable, so is $\max(f,g)$.
\end{proposition}

\begin{proof}
By Lemma~\ref{lem:maxrelu}, $\max(f,g) = f + \ReLU(g + (-1)\cdot f)$, built from
$f,g$ by scaling, addition, and rectification.
\end{proof}

\begin{proposition}[Tropical polynomials are network-computable]\label{prop:tp}
Every tropical polynomial is network-computable.
\end{proposition}

\begin{proof}[Proof sketch]
A tropical polynomial is a maximum over a finite nonempty piece set $S$. Induct on
$S$: the single-piece case is an affine functional; adjoining a piece is a pairwise
maximum, preserved by Proposition~\ref{prop:max}.
\end{proof}

\begin{corollary}[Converse direction]\label{cor:converse}
Every tropical rational function is network-computable.
\end{corollary}

\begin{proof}
Write $f = p-q = p + (-1)\cdot q$; both $p,q$ are network-computable by
Proposition~\ref{prop:tp}, and the class is closed under scaling and addition.
\end{proof}

\begin{theorem}[Depth-free characterization]\label{thm:depth}
A function $f : \R^d \to \R$ is network-computable --- i.e.\ computable by a
feed-forward ReLU network of arbitrary finite depth and width --- if and only if
it is a tropical rational function.
\end{theorem}

\begin{proof}
Combine Corollary~\ref{cor:forward} and Corollary~\ref{cor:converse}.
\end{proof}

\begin{remark}
No hypothesis on depth or width is needed: the four generating operations of a
network coincide with the closure operations of the difference structure of the
max-plus semiring. Depth affects the size of piece sets, and thus efficiency, but
never the class of representable functions.
\end{remark}

\section{The decision boundary lies on an algebraic hypersurface}\label{sec:variety}
Fix a tropical rational classifier $f = p-q$ with explicit piece sets
\[
  p(x) = \max_{(a,b)\in S_p}\big(\ip{a}{x}+b\big), \qquad
  q(x) = \max_{(c,e)\in S_q}\big(\ip{c}{x}+e\big),
\]
where $S_p, S_q$ are finite and nonempty.

\begin{definition}[Affine polynomial]
To each affine functional $(a,b)$ associate the degree-$\le 1$ polynomial
$P_{(a,b)} = b + \sum_{j=1}^{d} a_j X_j \in \R[X_1,\dots,X_d]$, so that
$P_{(a,b)}(x) = \ip{a}{x}+b$.
\end{definition}

\begin{definition}[Boundary polynomial]
The \emph{boundary polynomial} of $(S_p, S_q)$ is
\[
  B_{S_p,S_q} \;=\; \prod_{(a,b)\in S_p}\;\prod_{(c,e)\in S_q}
     \big(P_{(a,b)} - P_{(c,e)}\big) \;\in\; \R[X_1,\dots,X_d].
\]
It has degree at most $|S_p|\cdot|S_q|$, each factor being an affine polynomial
cutting out the hyperplane where one piece of $p$ ties one piece of $q$.
\end{definition}

\begin{lemma}[Evaluation]\label{lem:eval}
For all $x$,
$B_{S_p,S_q}(x) = \prod_{(a,b)\in S_p}\prod_{(c,e)\in S_q}
\big((\ip{a}{x}+b) - (\ip{c}{x}+e)\big)$.
\end{lemma}

\begin{proof}
Evaluation is a ring homomorphism, so it commutes with products and differences.
\end{proof}

\begin{lemma}[Attained pieces]\label{lem:attained}
If $p(x)=q(x)$, there exist $(a,b)\in S_p$ and $(c,e)\in S_q$ with
$\ip{a}{x}+b = \max(p(x),q(x)) = \ip{c}{x}+e$.
\end{lemma}

\begin{proof}
Finiteness and nonemptiness of $S_p$ imply the max defining $p(x)$ is attained by
some $(a,b)$; likewise for $q(x)$. Since $p(x)=q(x)$, both equal $\max(p(x),q(x))$.
\end{proof}

\begin{theorem}[Algebraic boundary containment]\label{thm:variety}
The decision boundary of $f = p-q$ is contained in the real zero locus of the
boundary polynomial:
\[
  \partial(p-q) = \{\, x : p(x)=q(x) \,\} \;\subseteq\;
  \{\, x : B_{S_p,S_q}(x)=0 \,\}.
\]
In particular the piecewise-linear decision boundary lies inside the algebraic
hypersurface defined by the single polynomial $B_{S_p,S_q}$.
\end{theorem}

\begin{proof}
Let $x$ satisfy $p(x)=q(x)$. By Lemma~\ref{lem:attained} there are pieces
$(a,b)\in S_p$, $(c,e)\in S_q$ with $\ip{a}{x}+b = \ip{c}{x}+e$, so the
corresponding factor vanishes. A product is zero when one factor is zero, so by
Lemma~\ref{lem:eval}, $B_{S_p,S_q}(x)=0$.
\end{proof}

\begin{remark}
The inclusion is generally strict. The polynomial $B_{S_p,S_q}$ vanishes on every
tie-hyperplane, including \emph{phantom crossings} where two pieces tie but neither
attains the overall maximum. The variety is thus a faithful outer approximation:
it contains the boundary exactly, plus lower-dimensional phantom sheets.
\end{remark}

\begin{corollary}[Degree bound]
The decision boundary of a classifier with $m=|S_p|$ and $k=|S_q|$ pieces lies on
an algebraic hypersurface of degree at most $m\cdot k$.
\end{corollary}

\section{Worked examples}
\begin{example}
For affine functionals $(a_1,b_1),(a_2,b_2)$ and scalar $c$, the function
$x \mapsto c\,\ReLU(\ip{a_1}{x}+b_1) + \ReLU(\ip{a_2}{x}+b_2)$ is
network-computable, hence tropical rational by Theorem~\ref{thm:depth}.
\end{example}

\begin{example}
The classifier $f(x)=|x_1|$ is tropical rational: $|x_1| = \max(x_1,-x_1) - 0$. With
$S_p=\{(e_1,0),(-e_1,0)\}$, $S_q=\{(0,0)\}$, the boundary polynomial is
$B(x) = (X_1)(-X_1) = -X_1^2$, whose zero locus is exactly the true boundary
$\{x_1=0\}$; here containment is equality.
\end{example}

\section{Algorithms}
\textbf{Boundary polynomial construction.} Given $S_p, S_q$, form for each pair of
pieces the affine difference and multiply all $mk$ factors; complexity $O(mk)$
affine factors of size $O(d)$, expanded degree $mk$.

\smallskip
\textbf{Boundary membership test.} Evaluate $p(x), q(x)$ and test equality
($O((m+k)d)$); confirm by evaluating $B_{S_p,S_q}(x)$ as a product of $mk$ affine
evaluations.

\smallskip
\textbf{Max-to-ReLU compilation.} Repeatedly apply $\max(a,b)=a+\ReLU(b-a)$ to
compile a max-of-affines into a ReLU network, realizing the converse constructively.

\section{Future directions}
\textbf{Conjecture 1 (Minimal algebraic degree equals essential piece count).} The
minimal degree of an algebraic hypersurface containing the boundary equals the
number of pieces active on the boundary, which can be far below $m\cdot k$; inactive
factors are removable, so the true complexity is governed by an activation pattern.

\smallskip
\textbf{Conjecture 2 (Depth compresses algebraic degree exponentially).} There
exist hypersurfaces whose shallow-network boundary polynomial has degree
exponential in $d$ but whose deep-network realization has polynomial degree;
composition multiplies piece counts, so depth trades width for iterated
composition.

\smallskip
\textbf{Conjecture 3 (Reducibility at shared pieces).} The boundary variety factors
into irreducible affine hyperplanes, and two classifiers are boundary-equivalent iff
their essential hyperplane factors coincide as sets.

\section{Conclusion}
ReLU networks of arbitrary depth compute exactly the tropical rational functions,
and the decision boundary of any such classifier lies inside an explicit algebraic
hypersurface cut out by the product of pairwise affine differences of its pieces.
The first result removes depth as a variable in qualitative expressivity; the
second turns a piecewise-linear boundary into an object of classical algebraic
geometry with a written-down equation.

