from __future__ import annotations
from itertools import product
from typing import Dict, List, Sequence, Tuple

Piece = Tuple[Tuple[float, ...], float]
# A polynomial in d vars is a dict {exponent-tuple: coefficient}.
Poly = Dict[Tuple[int, ...], float]

def affine_poly(piece: Piece, d: int) -> Poly:
    """Return the degree-<=1 polynomial b + sum a_j X_j for an affine piece."""
    a, b = piece
    poly: Poly = {}
    if b != 0.0:
        poly[tuple([0] * d)] = b
    for j in range(d):
        if a[j] != 0.0:
            e = [0] * d; e[j] = 1
            poly[tuple(e)] = poly.get(tuple(e), 0.0) + a[j]
    return poly

def poly_sub(p: Poly, q: Poly) -> Poly:
    r = dict(p)
    for e, c in q.items():
        r[e] = r.get(e, 0.0) - c
        if abs(r[e]) < 1e-15:
            del r[e]
    return r

def poly_mul(p: Poly, q: Poly) -> Poly:
    r: Poly = {}
    for e1, c1 in p.items():
        for e2, c2 in q.items():
            e = tuple(a + b for a, b in zip(e1, e2))
            r[e] = r.get(e, 0.0) + c1 * c2
    return r

def boundary_polynomial(p_pieces: Sequence[Piece], q_pieces: Sequence[Piece], d: int) -> Poly:
    """Build B = prod_{A in Sp} prod_{C in Sq} (A - C) as an explicit polynomial."""
    result: Poly = {tuple([0] * d): 1.0}
    for a_piece, c_piece in product(p_pieces, q_pieces):
        factor = poly_sub(affine_poly(a_piece, d), affine_poly(c_piece, d))
        result = poly_mul(result, factor)
    return result

from __future__ import annotations
from typing import List, Sequence, Tuple

Piece = Tuple[Tuple[float, ...], float]

class Node:
    """A node in a ReLU computation graph (arbitrary depth)."""
    def __init__(self, kind: str, data=None, children: List["Node"] = None):
        self.kind = kind          # 'aff' | 'add' | 'scale' | 'relu'
        self.data = data          # Piece for 'aff'; scalar for 'scale'
        self.children = children or []

def compile_max_of_affines(pieces: Sequence[Piece]) -> Node:
    """Compile a tropical polynomial (max of affine pieces) into a ReLU network,
    using the identity  max(a, b) = a + ReLU(b - a)  repeatedly."""
    assert pieces, "need at least one affine piece"
    current = Node("aff", data=pieces[0])
    for piece in pieces[1:]:
        b = Node("aff", data=piece)
        neg_a = Node("scale", data=-1.0, children=[current])
        diff = Node("add", children=[b, neg_a])          # b - a
        relu_diff = Node("relu", children=[diff])         # ReLU(b - a)
        current = Node("add", children=[current, relu_diff])  # a + ReLU(b - a)
    return current

def eval_node(node: Node, x: Sequence[float]) -> float:
    if node.kind == "aff":
        a, b = node.data
        return sum(ai * xi for ai, xi in zip(a, x)) + b
    if node.kind == "scale":
        return node.data * eval_node(node.children[0], x)
    if node.kind == "add":
        return sum(eval_node(c, x) for c in node.children)
    if node.kind == "relu":
        return max(eval_node(node.children[0], x), 0.0)
    raise ValueError(node.kind)

