from __future__ import annotations
from typing import Sequence, Tuple

Piece = Tuple[Tuple[float, ...], float]

def aff_eval(piece: Piece, x: Sequence[float]) -> float:
    a, b = piece
    return sum(ai * xi for ai, xi in zip(a, x)) + b

def on_boundary(p_pieces, q_pieces, x, tol: float = 1e-9) -> bool:
    """Test whether x lies on the decision boundary {p = q}."""
    p = max(aff_eval(pp, x) for pp in p_pieces)
    q = max(aff_eval(qq, x) for qq in q_pieces)
    return abs(p - q) <= tol

def on_variety(p_pieces, q_pieces, x, tol: float = 1e-9) -> bool:
    """Test whether x lies on the boundary variety {B = 0}, by checking whether
    any pairwise affine difference vanishes (a product is zero iff a factor is)."""
    for a in p_pieces:
        for c in q_pieces:
            if abs(aff_eval(a, x) - aff_eval(c, x)) <= tol:
                return True
    return False
